<?php require 'config/db.php'; $count=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();if($count>0)exit('Setup sudah selesai. Hapus file setup.php dan buka login.php.');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['nama']??'');$username=trim($_POST['username']??'');$pass=$_POST['password']??'';if(strlen($name)<3||strlen($username)<3||strlen($pass)<12)$error='Nama dan username minimal 3 karakter, password minimal 12 karakter.';else{$s=$pdo->prepare("INSERT INTO users(nama,username,password_hash,role) VALUES (?,?,?,'admin')");$s->execute([$name,$username,password_hash($pass,PASSWORD_DEFAULT)]);redirect('login.php?setup=1');}}?><!doctype html><html lang="id"><meta charset="utf-8"><link rel="stylesheet" href="assets/style.css"><body class="login-page"><div class="login-left"><div><h1>SI-MAPAN ODGJ</h1><p>Setup administrator pertama</p></div></div><div class="login-right"><div class="login-card"><h1>Buat Admin</h1><p>Hanya dapat digunakan sebelum akun pertama dibuat</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="field"><label>Nama</label><input name="nama" required></div><div class="field"><label>Username</label><input name="username" required></div><div class="field"><label>Password (min. 12 karakter)</label><input name="password" type="password" minlength="12" required></div><button class="btn">Buat Akun Administrator</button></form></div></div></body></html>
